```python
def jsonable_encoder(
    obj: Any,
    include: Set[str] = None,
    exclude: Set[str] = set(),
    by_alias: bool = False,
    include_none: bool = True,
    custom_encoder: dict = {},
) -> Any:
    if isinstance(obj, BaseModel):
        model_dict = obj.dict(include=include, exclude=exclude, by_alias=by_alias)
        if hasattr(obj.Config, 'json_encoders') and obj.Config.json_encoders:
            return jsonable_encoder(model_dict, include_none=include_none, custom_encoder=obj.Config.json_encoders)
        return jsonable_encoder(model_dict, include_none=include_none)

    if isinstance(obj, Enum):
        return obj.value
    if isinstance(obj, (str, int, float, type(None))):
        return obj
    if isinstance(obj, dict):
        return {
            jsonable_encoder(
                key,
                by_alias=by_alias,
                include_none=include_none,
                custom_encoder=custom_encoder,
            ): jsonable_encoder(
                value,
                by_alias=by_alias,
                include_none=include_none,
                custom_encoder=custom_encoder,
            )
            for key, value in obj.items()
            if value is not None or include_none
        }
    if isinstance(obj, (list, set, frozenset, GeneratorType, tuple)):
        return [
            jsonable_encoder(
                item,
                include=include,
                exclude=exclude,
                by_alias=by_alias,
                include_none=include_none,
                custom_encoder=custom_encoder,
            )
            for item in obj
        ]

    errors = []
    try:
        encoder = custom_encoder.get(type(obj), ENCODERS_BY_TYPE.get(type(obj)))
        if encoder:
            return encoder(obj)
    except KeyError as e:
        errors.append(e)
    except Exception as e:
        errors.append(e)

    try:
        data = dict(obj)
    except Exception:
        try:
            data = vars(obj)
        except Exception as e:
            errors.append(e)
            raise ValueError(errors)
    return jsonable_encoder(data, by_alias=by_alias, include_none=include_none)
